ALTER POLICY paid_vehicle_display ON public.posts USING (true);
CREATE OR REPLACE FUNCTION public.open_vehicle_chat(_post uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post AND module='vehicle' AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id); IF p.id IS NULL OR p.user_id=caller THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; INSERT INTO public.post_chat_pairs(post_id,member_id,owner_id) VALUES(p.id,caller,p.user_id) ON CONFLICT DO NOTHING; RETURN p.user_id; END $$;
REVOKE ALL ON FUNCTION public.open_vehicle_chat(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.open_vehicle_chat(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_post_details(_post uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN SELECT * INTO p FROM public.posts WHERE id=_post AND (user_id=auth.uid() OR (status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id))); IF p.id IS NULL THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; IF p.module='vehicle' AND NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; RETURN jsonb_build_object('description',p.description,'goods_type',p.goods_type,'capacity_tons',p.capacity_tons,'trip_date',p.trip_date,'contact_phone',CASE WHEN p.module='vehicle' AND p.show_contact THEN p.contact_phone ELSE NULL END); END $$;
COMMENT ON FUNCTION public.open_vehicle_chat(uuid) IS 'Paid participant pair creation only; never inserts messages, notifications or bell demand rows. Vehicle contact disclosure remains owner-consented.';